def write_tree(root: Path) -> None:
    """Write every fixture file below root."""
    for package in sorted(PACKAGES):
        for relative, text in sorted(PACKAGES[package].items()):
            path = root / package / relative
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(text.encode("utf-8"))


def compare(root: Path) -> list[str]:
    """Return a line per difference between the table and the tree below root."""
    differences: list[str] = []
    expected: set[str] = set()
    for package in sorted(PACKAGES):
        for relative, text in sorted(PACKAGES[package].items()):
            expected.add(f"{package}/{relative}")
            path = root / package / relative
            if not path.is_file():
                differences.append(f"missing: {package}/{relative}")
                continue
            if path.read_bytes() != text.encode("utf-8"):
                differences.append(f"differs: {package}/{relative}")
    if root.is_dir():
        for path in sorted(root.rglob("*")):
            if path.is_file():
                relative = path.relative_to(root).as_posix()
                if relative not in expected:
                    differences.append(f"unexpected: {relative}")
    return differences


def main() -> int:
    parser = argparse.ArgumentParser(description="Generate the wolf test fixture packages.")
    parser.add_argument("--output", type=Path, help="directory to write the fixture packages into")
    parser.add_argument("--check", type=Path, metavar="DIR",
                        help="compare an existing tree against the table and fail on any difference")
    parser.add_argument("--list", action="store_true", help="print the package names")
    args = parser.parse_args()

    if args.list:
        for package in sorted(PACKAGES):
            print(package)
        return 0

    if args.check is not None:
        differences = compare(args.check)
        for line in differences[:50]:
            print(line, file=sys.stderr)
        if differences:
            print(f"{len(differences)} differences against {args.check}", file=sys.stderr)
            return 1
        print(f"{len(PACKAGES)} packages match {args.check}")
        return 0

    if args.output is None:
        parser.error("one of --output, --check or --list is required")
    write_tree(args.output)
    files = sum(len(files) for files in PACKAGES.values())
    print(f"{len(PACKAGES)} packages, {files} files written to {args.output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
